var e={title:`Взлом и страховка`,category:`digital`,budget:2e3,scenes:[{id:1,title:`💻 Разговор в школе`,bg:`images/stories/12+/vzlom-akkaunta/school-bg.png`,characters:[{name:`Виктория`,img:`images/characters/viktoria/viktoria.png`,side:`left`},{name:`Матвей`,img:`images/characters/matvey/matvey.png`,side:`right`}],dialogues:[{speaker:`Виктория`,text:`Слышал, у нас в параллели кому-то взломали страницу ВКонтакте? Говорят, за последний год взломов стало в два раза больше.`},{speaker:`Матвей`,text:`Да, страшно. Я слышал, что многие используют простые пароли типа "12345". Но мы же с тобой умнее?`}],choices:[{id:`learnMore`,title:`Узнать о защите`,price:0,description:`Как обезопасить аккаунт`,icon:`shield`}]},{id:2,title:`🛡️ Страховка от взлома`,bg:`images/stories/12+/vzlom-akkaunta/school-bg.png`,characters:[{name:`Виктория`,img:`images/characters/viktoria/viktoria.png`,side:`left`},{name:`Матвей`,img:`images/characters/matvey/matvey.png`,side:`right`}],dialogues:[{speaker:`Матвей`,text:`Слушай, я тут читал, что теперь можно застраховать свой аккаунт. Полис покрывает восстановление после взлома и даже услуги психолога, если кто-то начнёт травить.`},{speaker:`Виктория`,text:`Ого! Это стоит всего 1000 рублей в год, а сумма покрытия — до 1 миллиона. Но стоит ли?`},{speaker:`Матвей`,text:`Четверть россиян уже теряли аккаунты. И половина из них — молодёжь. Я бы застраховался.`}],choices:[{id:`buyInsurance`,title:`Купить страховку (1000₽)`,price:1e3,description:`Защитить аккаунт`,icon:`shield`},{id:`noInsurance`,title:`Не покупать`,price:0,description:`Надеяться на удачу`,icon:`cross`}]},{id:3,title:`🎣 Фишинг!`,bg:`images/stories/12+/vzlom-akkaunta/school-bg.png`,characters:[{name:`Виктория`,img:`images/characters/viktoria/viktoria.png`,side:`left`},{name:`Матвей`,img:`images/characters/matvey/matvey.png`,side:`right`}],dialogues:[{speaker:`Матвей`,text:`О, смотри, ссылка в личку: "Ваш аккаунт заблокирован! Перейдите по ссылке для восстановления".`},{speaker:`Виктория`,text:`Стой! Это похоже на фишинг. Я слышала, так воруют пароли. Давай проверим!`}],miniGame:{type:`qte`,title:`Распознай фишинг!`,instruction:`Быстро нажимай кнопку, чтобы не дать перейти по ссылке!`},dialoguesAfterGame:{success:[{speaker:`Матвей`,text:`Фух! Успели! Я чуть не кликнул. Ты меня спасла!`},{speaker:`Виктория`,text:`Главное — вовремя заметить. А ещё я подключила двухфакторную аутентификацию — так надёжнее.`}],fail:[{speaker:`Матвей`,text:`Ой! Я перешёл по ссылке... И ввёл пароль. Аккаунт взломан!`},{speaker:`Виктория`,text:`Что же делать? Мой аккаунт тоже взломали — я когда-то дала тебе свой пароль...`}]}},{id:4,title:`💔 Последствия`,bg:`images/stories/12+/vzlom-akkaunta/school-bg.png`,characters:[{name:`Виктория`,img:`images/characters/viktoria/viktoria.png`,side:`left`},{name:`Матвей`,img:`images/characters/matvey/matvey.png`,side:`right`}],dialogues:{withProtectionAndHacked:[{speaker:`Матвей`,text:`Аккаунт взломали... Но у нас же страховка!`},{speaker:`Виктория`,text:`Да! Я уже написала в поддержку, они сказали, что восстановят всё бесплатно.`}],withProtectionAndSafe:[{speaker:`Виктория`,text:`Обошлось! Но я рада, что страховка есть. Мало ли что...`},{speaker:`Матвей`,text:`Согласен. Спокойствие дороже.`}],withoutProtectionAndHacked:[{speaker:`Матвей`,text:`Аккаунт взломали. Вся переписка удалена, а друзьям рассылают спам...`},{speaker:`Виктория`,text:`И восстановление стоит денег... Зачем мы не купили страховку?`}],withoutProtectionAndSafe:[{speaker:`Виктория`,text:`Пронесло! Но я поняла, как легко всё потерять.`},{speaker:`Матвей`,text:`Давай больше не будем рисковать. В следующий раз — только со страховкой.`}]},choices:[{id:`next`,title:`Дальше`,price:0,description:``,icon:`arrow`}]},{id:5,title:`😢 Горький урок`,bg:`images/stories/12+/vzlom-akkaunta/school-bg.png`,characters:[{name:`Виктория`,img:`images/characters/viktoria/viktoria.png`,side:`left`},{name:`Матвей`,img:`images/characters/matvey/matvey.png`,side:`right`}],available:`withoutProtectionAndHacked`,dialogues:[{speaker:`Виктория`,text:`Я чувствую себя глупо. Мы могли бы избежать этого.`},{speaker:`Матвей`,text:`Давай представим, что можно всё исправить. Попробуем ещё раз со страховкой?`}],choices:[{id:`retry`,title:`Попробовать со страховкой`,price:0,description:`Вернуться к выбору`,icon:`restart`},{id:`finishSad`,title:`Принять урок`,price:0,description:`Идти дальше`,icon:`eye`}],nextScene:1},{id:6,title:`🔐 Урок усвоен`,bg:`images/stories/12+/vzlom-akkaunta/school-bg.png`,characters:[{name:`Виктория`,img:`images/characters/viktoria/viktoria.png`,side:`left`},{name:`Матвей`,img:`images/characters/matvey/matvey.png`,side:`right`}],dialogues:{withProtection:[{speaker:`Матвей`,text:`Теперь я знаю: страховка аккаунта — это не роскошь, а необходимость.`},{speaker:`Виктория`,text:`И двухфакторка с надёжным паролем. Кстати, Матвей, спасибо, что был рядом.`},{speaker:`Матвей`,text:`(Краснеет) Может, вместе настроим защиту и на твоём аккаунте?`}],withoutProtection:[{speaker:`Матвей`,text:`Я запомню этот урок. Больше никаких простых паролей и переходов по подозрительным ссылкам.`},{speaker:`Виктория`,text:`И обязательно застрахуем аккаунты. Цифровая гигиена — это серьёзно.`}]},choices:[{id:`finish`,title:`Завершить историю`,price:0,description:``,icon:`trophy`}]}],widgets:{chat:{available:!1},call:{available:!1}}};export{e as default};